def minimax_bitmask(n):
    memo = {}

    def get_moves(player, mask_A, mask_B):
        moves = []
        current_mask = mask_A if player == 'A' else mask_B
        all_mask = mask_A | mask_B
        for x in range(n):
            if not (all_mask & (1 << x)):
                # check if x-1 or x+1 is in current_mask
                is_consecutive = False
                if x > 0 and (current_mask & (1 << (x - 1))):
                    is_consecutive = True
                if x < n - 1 and (current_mask & (1 << (x + 1))):
                    is_consecutive = True
                if not is_consecutive:
                    moves.append(x)
        return moves

    def play(player, mask_A, mask_B):
        state = (player, mask_A, mask_B)
        if state in memo:
            return memo[state]

        moves = get_moves(player, mask_A, mask_B)

        if not moves:
            return -1 if player == 'A' else 1

        results = []
        for x in moves:
            if player == 'A':
                new_mask_A = mask_A | (1 << x)
                new_mask_B = mask_B
            else:
                new_mask_A = mask_A
                new_mask_B = mask_B | (1 << x)

            if (new_mask_A | new_mask_B) == (1 << n) - 1:
                results.append(0)
            else:
                next_player = 1 if player == 0 else 0 # 0 for Alice, 1 for Bob
                results.append(play(1 - player, new_mask_A, new_mask_B))

        if player == 0: # Alice
            res = max(results)
        else: # Bob
            res = min(results)

        memo[state] = res
        return res

    return play(0, 0, 0)

